CREATE TABLE legal_policies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id), policy_key TEXT NOT NULL, name TEXT NOT NULL, policy_type TEXT NOT NULL, jurisdiction_code TEXT, language TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,policy_key));
CREATE TABLE legal_policy_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), legal_policy_id UUID NOT NULL REFERENCES legal_policies(id), version INTEGER NOT NULL, content_reference TEXT NOT NULL, content_hash TEXT NOT NULL, effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, publication_status TEXT NOT NULL, published_by UUID, published_at TIMESTAMPTZ, supersedes_version_id UUID REFERENCES legal_policy_versions(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(legal_policy_id,version));
CREATE TABLE policy_assignments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), legal_policy_version_id UUID NOT NULL REFERENCES legal_policy_versions(id), target_type TEXT NOT NULL, target_id UUID NOT NULL, mandatory BOOLEAN NOT NULL, acceptance_required BOOLEAN NOT NULL, effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE policy_acceptances (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), legal_policy_version_id UUID NOT NULL REFERENCES legal_policy_versions(id), principal_type TEXT NOT NULL, principal_id UUID NOT NULL, acceptance_method TEXT NOT NULL, accepted_at TIMESTAMPTZ NOT NULL, source_context TEXT NOT NULL, evidence_reference TEXT NOT NULL, withdrawn_at TIMESTAMPTZ, withdrawal_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE consent_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), principal_id UUID NOT NULL, consent_type TEXT NOT NULL, policy_version_id UUID NOT NULL REFERENCES legal_policy_versions(id), status TEXT NOT NULL, granted_at TIMESTAMPTZ NOT NULL, withdrawn_at TIMESTAMPTZ, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE legal_holds (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), object_type TEXT NOT NULL, object_id UUID NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL, placed_by UUID NOT NULL, placed_at TIMESTAMPTZ NOT NULL, released_by UUID, released_at TIMESTAMPTZ, release_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX legal_holds_active_idx ON legal_holds(workspace_id,object_type,object_id) WHERE status='ACTIVE';
CREATE TABLE signature_policies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), jurisdiction_code TEXT NOT NULL, contract_type TEXT NOT NULL, transaction_type TEXT NOT NULL, assurance_level TEXT NOT NULL, witness_required BOOLEAN NOT NULL, status TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1);
